import { World3d } from "rust-wasm";

const wCoords: [number, number, number, number][] = [
	[0, 0, 0, 2.5],
	[-1, -1, 0, 2.5],
	[-2, -1, 0, 2.5],
	[-2, 0, 0, 2.5],
	[-2, 1, 0, 2.5],
	[-2, 2, 0, 2.5],
	[1, -1, 0, 2.5],
	[2, 0, 0, 2.5],
	[2, 1, 0, 2.5],
	[2, -1, 0, 2.5],
	[2, 2, 0, 2.5],
];

const plot = (
	offsetX: number,
	offsetY: number,
	offsetZ: number,
	amount: number,
	center: number,
): [number, number, number, number] => {
	return [center + offsetX, center + offsetY, center + offsetZ, amount];
};

export default (world: World3d, center: number) => {
	wCoords.forEach((item) => {
		world.add_density(...plot(...item, center));
	});
};
