import init, {
	init_world_2d,
	init_world_3d,
	World2d,
	World3d,
} from "rust-wasm";
import { resolveWorldConfig, type WorldConfig } from "./lib/config";
import { createRenderer } from "./lib/renderer";
import { initHud } from "./lib/hud";
import { initMouseListeners } from "./lib/events";
import render2d from "./lib/components/2d/render2d";
import render3d from "./lib/components/3d/render3d";
import type { RenderState } from "./lib/types";

export type World = World2d | World3d;

type InitFn<W extends World> = (
	n: number,
	diffusion: number,
	viscocity: number,
	dt: number,
	decay: number,
) => W;
type RenderFn<W extends World> = (state: RenderState<W>) => () => void;

let disposeActiveWorld: (() => void) | undefined;

const initWorld = async <W extends World>(
	worldConfig: WorldConfig,
	initFn: InitFn<W>,
	renderFn: RenderFn<W>,
) => {
	const config = resolveWorldConfig(worldConfig);
	disposeActiveWorld?.();
	const disposeMouseListeners = initMouseListeners({
		canvas: config.canvas,
		n: config.n,
	});
	const renderer = createRenderer(config.canvas);
	const wasm = await init();
	const world = initFn(
		config.n,
		config.diffusion,
		config.viscocity,
		config.dt,
		config.decay,
	);
	const disposeRender = renderFn({
		world,
		wasm,
		config,
		hud: initHud(config),
		renderer,
	});
	disposeActiveWorld = () => {
		disposeRender();
		disposeMouseListeners();
	};
};

export const initWorld2d = (worldConfig: WorldConfig = {}) =>
	initWorld(worldConfig, init_world_2d, render2d);

export const initWorld3d = (worldConfig: WorldConfig = {}) =>
	initWorld(worldConfig, init_world_3d, render3d);

export type { WorldConfig } from "./lib/config";
