import baseImage from "./baseImage";
import mouseVelocity from "./mouseVelocity";
import { updateHud, type HudState } from "../../hud";
import { createDrawSlice } from "../../components/shaders/drawSlice";
import type { RenderState } from "../../types";
import { World2d } from "rust-wasm";

export default (state: RenderState<World2d>) => {
	const drawSlice = createDrawSlice(
		state.renderer,
		state.config.n,
		state.config.colorProfile,
	);

	const frameLoop = state.renderer.regl.frame(() => {
		// DRAW
		drawSlice(state);
		updateHud(state.hud);
		// STATE
		state.world.step();
		// baseImage(state.world, state.config.center);
		mouseVelocity(state.world, state.config);
	});

	return () => {
		frameLoop.cancel();
		state.renderer.destroy();
	};
};
