import { mat4 } from "gl-matrix";
import type { Renderer } from "../../renderer";

export const createDrawFrame = ({ regl }: Renderer) => {
	const projectionMatrix = mat4.create();
	const viewMatrix = mat4.create();
	const pvMatrix = mat4.create();

	mat4.ortho(projectionMatrix, -1.5, 1.5, -1.5, 1.5, 0.1, 10);
	mat4.lookAt(viewMatrix, [1, 1, 1], [0, 0, 0], [0, 1, 0]);
	mat4.multiply(pvMatrix, projectionMatrix, viewMatrix);
	const pvUniform = Array.from(pvMatrix);

	const drawFrame = regl({
		vert: `
	precision mediump float;
	attribute vec3 position;
	uniform mat4 uPV;
	
	void main() {
		gl_Position = uPV * vec4(position, 1.0);
	}`,

		frag: `
	precision mediump float;
	void main() {
		gl_FragColor = vec4(0.5, 0.5, 0.5, 0.4);
	}`,

		attributes: {
			position: [
				// Bottom Square
				[-0.5, -0.5, -0.5],
				[0.5, -0.5, -0.5],
				[0.5, -0.5, -0.5],
				[0.5, -0.5, 0.5],
				[0.5, -0.5, 0.5],
				[-0.5, -0.5, 0.5],
				[-0.5, -0.5, 0.5],
				[-0.5, -0.5, -0.5],

				// Top Square
				[-0.5, 0.5, -0.5],
				[0.5, 0.5, -0.5],
				[0.5, 0.5, -0.5],
				[0.5, 0.5, 0.5],
				[0.5, 0.5, 0.5],
				[-0.5, 0.5, 0.5],
				[-0.5, 0.5, 0.5],
				[-0.5, 0.5, -0.5],

				// Pillars
				[-0.5, -0.5, -0.5],
				[-0.5, 0.5, -0.5],
				[0.5, -0.5, -0.5],
				[0.5, 0.5, -0.5],
				[0.5, -0.5, 0.5],
				[0.5, 0.5, 0.5],
				[-0.5, -0.5, 0.5],
				[-0.5, 0.5, 0.5],
			],
		},

		uniforms: {
			uPV: pvUniform,
		},
		blend: {
			enable: true,
			func: {
				srcRGB: "src alpha",
				srcAlpha: 1,
				dstRGB: "one minus src alpha",
				dstAlpha: 1,
			},
		},
		primitive: "lines",
		count: 24,
	});

	return () => {
		drawFrame();
	};
};
