import { getMouseState } from "../../events";
import { World2d } from "rust-wasm";
import type { ResolvedWorldConfig } from "../../config";

export default (world: World2d, config: ResolvedWorldConfig) => {
	const {
		mouseEffectAmplitude: EFFECT_AMPLITUDE,
		mouseEffectRadius: EFFECT_RADIUS,
	} = config;
	const { mouseX, mouseY, vX, vY } = getMouseState();

	const speed = Math.abs(vX) + Math.abs(vY);

	for (let dx = -EFFECT_RADIUS; dx <= EFFECT_RADIUS; dx += 1) {
		for (let dy = -EFFECT_RADIUS; dy <= EFFECT_RADIUS; dy += 1) {
			const dist = Math.sqrt(dx * dx + dy * dy);
			if (dist > EFFECT_RADIUS) continue;

			// Smooth ease-off: 1 at centre, 0 at radius edge
			const falloff = 1 - (dist / EFFECT_RADIUS) ** 2;

			const x = mouseX + dx;
			const y = mouseY + dy;

			world.add_density(x, y, speed * 0.5 * falloff * EFFECT_AMPLITUDE);
			world.add_velocity(
				x,
				y,
				vX * 0.1 * falloff * EFFECT_AMPLITUDE,
				vY * 0.1 * falloff * EFFECT_AMPLITUDE,
			);
		}
	}
};
