interface MouseState {
	mouseX: number;
	mouseY: number;
	vX: number;
	vY: number;
}

interface MouseListenersConfig {
	canvas: HTMLCanvasElement;
	n: number;
}

let state: MouseState = {
	mouseX: 0,
	mouseY: 0,
	vX: 0,
	vY: 0,
};

let disposeMouseListeners: (() => void) | undefined;
let stopTimer: ReturnType<typeof setTimeout> | undefined;

export function initMouseListeners({
	canvas,
	n,
}: MouseListenersConfig): () => void {
	disposeMouseListeners?.();

	const onMouseMove = (event: MouseEvent) => {
		const rect = canvas.getBoundingClientRect();
		const x = Math.floor(((event.clientX - rect.left) * n) / rect.width);
		const y = Math.floor(
			((rect.height - (event.clientY - rect.top)) * n) / rect.height,
		);

		state.vX = x - state.mouseX;
		state.vY = y - state.mouseY;
		state.mouseX = x;
		state.mouseY = y;

		clearTimeout(stopTimer);
		stopTimer = setTimeout(() => {
			state.vX = 0;
			state.vY = 0;
		}, 50);
	};

	document.addEventListener("mousemove", onMouseMove);
	disposeMouseListeners = () => {
		document.removeEventListener("mousemove", onMouseMove);
		clearTimeout(stopTimer);
	};

	return disposeMouseListeners;
}

export function getMouseState(): MouseState {
	return state;
}
