import { getMouseState } from "./events";
import type { ResolvedWorldConfig } from "./config";

export type HudState = {
	lastTime: number;
	frameCount: number;
	fps: number;
	mouseX: number;
	mouseY: number;
	vX: number;
	vY: number;
	elements: ResolvedWorldConfig["hud"];
};

export const initHud = (config: ResolvedWorldConfig): HudState => ({
	lastTime: performance.now(),
	frameCount: 0,
	fps: 0,
	mouseX: 0,
	mouseY: 0,
	vX: 0,
	vY: 0,
	elements: config.hud,
});

const setFps = (state: HudState) => {
	const now = performance.now();
	const dt = now - state.lastTime;
	state.frameCount++;

	if (dt >= 1000) {
		state.fps = state.frameCount;
		state.frameCount = 0;
		state.lastTime = now;
	}
	if (state.elements.fps) {
		state.elements.fps.innerText = `FPS: ${state.fps}`;
	}
};

export const updateHud = (state: HudState) => {
	const mouseState = getMouseState();
	state.mouseX = mouseState.mouseX;
	state.mouseY = mouseState.mouseY;
	state.vX = mouseState.vX;
	state.vY = mouseState.vY;
	if (state.elements.mouseX) {
		state.elements.mouseX.innerText = `X: ${state.mouseX}`;
	}
	if (state.elements.mouseY) {
		state.elements.mouseY.innerText = `Y: ${state.mouseY}`;
	}
	if (state.elements.mouseVX) {
		state.elements.mouseVX.innerText = `VX: ${state.vX}`;
	}
	if (state.elements.mouseVY) {
		state.elements.mouseVY.innerText = `VY: ${state.vY}`;
	}
	setFps(state);
};
