/**
 * Color profile definitions for density visualization.
 * Each profile contains a GLSL function that maps a normalized value [0,1] to an RGB color.
 */

export type ColorProfileName = "heatmap" | "greyscale";

export interface ColorProfile {
	name: ColorProfileName;
	glslFunction: string;
	label: string;
}

const HEATMAP: ColorProfile = {
	name: "heatmap",
	label: "Heatmap",
	glslFunction: `
    vec4 colorize(float t) {
      t = clamp(t, 0.0, 1.0);
      vec3 c0 = vec3(0.0,  0.0,  0.0);
      vec3 c1 = vec3(0.4,  0.0,  0.6);
      vec3 c2 = vec3(0.9,  0.3,  0.0);
      vec3 c3 = vec3(1.0,  0.85, 0.1);
      vec3 c4 = vec3(1.0,  1.0,  1.0);

      vec3 color;
      if (t < 0.20) color = mix(c0, c1, t / 0.20);
      else if (t < 0.40) color = mix(c1, c2, (t - 0.20) / 0.20);
      else if (t < 0.70) color = mix(c2, c3, (t - 0.40) / 0.30);
      else color = mix(c3, c4, (t - 0.70) / 0.30);

      return vec4(color, t);
    }
  `,
};

const GREYSCALE: ColorProfile = {
	name: "greyscale",
	label: "Greyscale",
	glslFunction: `
    vec4 colorize(float t) {
      t = clamp(t, 0.0, 1.0);
      return vec4(0.0, 0.0, 0.0, t);
    }
  `,
};

export const COLOR_PROFILES: Record<ColorProfileName, ColorProfile> = {
	heatmap: HEATMAP,
	greyscale: GREYSCALE,
};

export const COLOR_PROFILE_NAMES = Object.keys(
	COLOR_PROFILES,
) as ColorProfileName[];

export const getColorProfile = (name: ColorProfileName): ColorProfile => {
	return COLOR_PROFILES[name];
};
