import baseImage from "./baseImage";
import mouseVelocity from "./mouseVelocity";
import { updateHud, type HudState } from "../../hud";
import type { RenderState } from "../../types";
import { World3d } from "rust-wasm";
import { createDrawCube } from "../shaders/drawCube";
import { createDrawFrame } from "../shaders/drawFrame";

export default (state: RenderState<World3d>) => {
	const drawCube = createDrawCube(
		state.renderer,
		state.config.n,
		state.config.colorProfile,
	);
	const drawFrame = createDrawFrame(state.renderer);
	const frameLoop = state.renderer.regl.frame(() => {
		// DRAW
		drawCube(state);
		drawFrame();
		updateHud(state.hud);
		// STATE
		state.world.step();
		baseImage(state.world, state.config.center);
		mouseVelocity(state.world, state.config.center);
	});

	return () => {
		frameLoop.cancel();
		state.renderer.destroy();
	};
};
