export interface HudConfig {
	fps?: HTMLSpanElement | null;
	mouseX?: HTMLSpanElement | null;
	mouseY?: HTMLSpanElement | null;
	mouseVX?: HTMLSpanElement | null;
	mouseVY?: HTMLSpanElement | null;
}

export interface WorldConfig {
	n?: number;
	maxDensity?: number;
	decay?: number;
	diffusion?: number;
	viscocity?: number;
	dt?: number;
	mouseEffectAmplitude?: number;
	mouseEffectRadius?: number;
	canvas?: HTMLCanvasElement | null;
	hud?: HudConfig;
	colorProfile?: "heatmap" | "greyscale";
}

export interface ResolvedHudConfig {
	fps: HTMLSpanElement | null;
	mouseX: HTMLSpanElement | null;
	mouseY: HTMLSpanElement | null;
	mouseVX: HTMLSpanElement | null;
	mouseVY: HTMLSpanElement | null;
}

export interface ResolvedWorldConfig {
	n: number;
	center: number;
	maxDensity: number;
	decay: number;
	diffusion: number;
	viscocity: number;
	dt: number;
	mouseEffectAmplitude: number;
	mouseEffectRadius: number;
	canvas: HTMLCanvasElement;
	hud: ResolvedHudConfig;
	colorProfile: "heatmap" | "greyscale";
}

const DEFAULT_N = 312;
const DEFAULT_MAX_DENSITY = 50;
const DEFAULT_DYE_DECAY = 0.0005;
const DEFAULT_FLUID_DIFFUSION = 0.000001;
const DEFAULT_FLUID_VISCOCITY = 0.000001;
const DEFAULT_FLUID_DT = 0.5;
const DEFAULT_MOUSE_EFFECT_AMPLITUDE = 1;
const DEFAULT_MOUSE_EFFECT_RADIUS = 4;
const DEFAULT_COLOR_PROFILE = "heatmap" as const;

const getDefaultCanvas = (): HTMLCanvasElement => {
	const canvas = document.querySelector("#fluid-sim-canvas");

	if (!(canvas instanceof HTMLCanvasElement)) {
		throw new Error(
			"Fluid Sim requires a canvas element. Pass config.canvas or render into #fluid-sim-canvas.",
		);
	}

	return canvas;
};

const getDefaultHud = (): ResolvedHudConfig => ({
	fps: document.querySelector("#hud-fps") as HTMLSpanElement | null,
	mouseX: document.querySelector("#hud-mouse-x") as HTMLSpanElement | null,
	mouseY: document.querySelector("#hud-mouse-y") as HTMLSpanElement | null,
	mouseVX: document.querySelector("#hud-mouse-vx") as HTMLSpanElement | null,
	mouseVY: document.querySelector("#hud-mouse-vy") as HTMLSpanElement | null,
});

export const resolveWorldConfig = (
	config: WorldConfig = {},
): ResolvedWorldConfig => {
	const n = config.n ?? DEFAULT_N;
	const defaultHud = getDefaultHud();

	return {
		n,
		center: Math.floor((n - 1) / 2),
		maxDensity: config.maxDensity ?? DEFAULT_MAX_DENSITY,
		decay: config.decay ?? DEFAULT_DYE_DECAY,
		diffusion: config.diffusion ?? DEFAULT_FLUID_DIFFUSION,
		viscocity: config.viscocity ?? DEFAULT_FLUID_VISCOCITY,
		dt: config.dt ?? DEFAULT_FLUID_DT,
		mouseEffectAmplitude:
			config.mouseEffectAmplitude ?? DEFAULT_MOUSE_EFFECT_AMPLITUDE,
		mouseEffectRadius: config.mouseEffectRadius ?? DEFAULT_MOUSE_EFFECT_RADIUS,
		canvas: config.canvas ?? getDefaultCanvas(),
		hud: {
			fps: config.hud?.fps ?? defaultHud.fps,
			mouseX: config.hud?.mouseX ?? defaultHud.mouseX,
			mouseY: config.hud?.mouseY ?? defaultHud.mouseY,
			mouseVX: config.hud?.mouseVX ?? defaultHud.mouseVX,
			mouseVY: config.hud?.mouseVY ?? defaultHud.mouseVY,
		},
		colorProfile: config.colorProfile ?? DEFAULT_COLOR_PROFILE,
	};
};
